function lazyLoad(){const n=document.querySelectorAll(".lazy-img"),t=function(n,t){n.forEach(n=>{n.isIntersecting&&(n.target.src=n.target.dataset.src,t.unobserve(n.target))})},i=new IntersectionObserver(t,{root:null,threshold:.2});n.forEach(n=>i.observe(n))}function homePageSliderLazyLoad(){const n=document.querySelectorAll(".lazy-source"),t=function(n,t){n.forEach(n=>{if(n.isIntersecting){const i=n.target.previousElementSibling;n.target.srcset=n.target.dataset.srcset;t.unobserve(n.target);i.classList.add("d-none")}})},i=new IntersectionObserver(t,{root:null,threshold:.2});n.forEach(n=>i.observe(n))}